async def run():
    async with AsyncSessionLocal() as db:
        units = {u.unit_number: u for u in (await db.execute(select(Unit))).scalars().all()}
        total = 0
        for unit_num, items in ORDER.items():
            u = units.get(unit_num)
            if not u: continue
            nahw = (await db.execute(select(Lesson).where(
                Lesson.unit_id==u.id, Lesson.lesson_type=="nahw"))).scalar_one_or_none()
            if not nahw: continue
            # حذف أسئلة الترتيب القديمة (التي تحتوي رَتِّب)
            old = (await db.execute(select(Exercise).where(Exercise.lesson_id==nahw.id))).scalars().all()
            for e in old:
                if "رَتِّب" in (e.question_ar or ""):
                    await db.delete(e)
            await db.flush()
            num = 500
            for words, ans in items:
                num += 1
                db.add(Exercise(
                    unit_id=u.id, lesson_id=nahw.id, exercise_number=num,
                    exercise_type="fill_blank",
                    question_ar=f"رَتِّب الكلمات: {words}",
                    correct_answer=ans,
                    options=None, hint_ar="رتب الكلمات لتكوين جملة", difficulty=3, points=15,
                ))
                total += 1
            await db.flush()
            print(f"وحدة {unit_num}: 5 ترتيب")
        await db.commit()
        print(f"\nتم اضافة {total} سؤال ترتيب")

asyncio.run(run())